	if got := indexOf(numbers, 7); got != 1 {
		t.Fatalf("indexOf(numbers, 7) = %d, want 1", got)
	}
	if got := indexOf(numbers, 42); got != -1 {
		t.Fatalf("indexOf(numbers, 42) = %d, want -1", got)
	}

	words := []string{"go", "rust", "python"}
	if got := indexOf(words, "rust"); got != 1 {
		t.Fatalf("indexOf(words, \"rust\") = %d, want 1", got)
	}
	if got := indexOf(words, "java"); got != -1 {
		t.Fatalf("indexOf(words, \"java\") = %d, want -1", got)
	}
}

